const D = { density:.55, scale:1, hue:16, energy:.6, speed:1, x:.5, y:.5, eruption:.5, smoke:.6, style:'molten', seed:0, act:'smolder' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const u = Math.min(width, height);
const st = P.style;
const ashen = st==='ashen';
const thermal = st==='thermal';
const woodcut = st==='woodcut';
const blueprint = st==='blueprint';
const h = P.hue;
// dramaturgy: base eruption level from act + section arc
let actLvl = P.eruption;
if (P.act==='erupt') actLvl = P.eruption*0.4 + K.intensity*0.9;
else if (P.act==='flow') actLvl = P.eruption*0.7 + 0.2;
else actLvl = P.eruption*0.5 + K.intensity*0.3;
const erupt = Math.min(1.2, actLvl);
const key = width+'x'+height+'|'+P.seed+'|'+st+'|'+Math.round(h);
if (S.key !== key) {
  S.key = key;
  const g = createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100);
  g.noStroke();
  const hz = height*0.62;
  // sky
  for (let i=0;i<100;i++){ const t=i/100, y=t*height;
    if (blueprint) g.fill(210,55,6+t*4);
    else if (ashen) g.fill(30,8,10+t*14);
    else if (thermal) g.fill(240-t*40, 60, 8+t*10);
    else g.fill(h-6+t*10, 88-t*24, 10+t*30);
    g.rect(0,y,width,height/100+1);
  }
  // ground
  g.fill(blueprint?210:(ashen?30:h), blueprint?50:(ashen?10:70), blueprint?4:(ashen?6:6));
  g.rect(0,hz,width,height-hz);
  // mountain silhouette
  const peakY=hz-height*0.34, notchY=hz-height*0.30;
  const mtn=[[0,height],[0,hz+height*0.03],[width*0.24,hz-height*0.16],[width*0.40,peakY],[width*0.46,notchY],[width*0.54,notchY],[width*0.60,peakY],[width*0.78,hz-height*0.16],[width,hz+height*0.05],[width,height]];
  if (blueprint){ g.noFill(); g.stroke(195,70,60,80); g.strokeWeight(1.6); g.beginShape(); for(const p of mtn) g.vertex(p[0],p[1]); g.endShape();
    // strata contour lines
    g.strokeWeight(0.8); g.stroke(195,60,40,50);
    for(let s=1;s<6;s++){ const yy=hz - s*height*0.05; g.line(width*0.28,yy,width*0.72,yy); }
    g.noStroke();
  } else {
    g.fill(0,0, woodcut?0:(ashen?4:4));
    g.beginShape(); for(const p of mtn) g.vertex(p[0],p[1]); g.endShape(CLOSE);
    if (woodcut){ // hatching on mountain flank
      g.stroke(0,0,0,60); g.strokeWeight(1);
      for(let yy=peakY+height*0.04; yy<hz; yy+=u*0.02){ g.line(width*0.30,yy,width*0.5,yy+u*0.01); }
      g.noStroke();
    }
  }
  S.buf = g;
  S.hz=hz; S.peakX=width*0.5; S.peakY=notchY;
  // ember field
  const nEmber=Math.floor(24+P.density*120);
  S.emb=[]; for(let i=0;i<nEmber;i++) S.emb.push({off:fr(i)*6.28,spd:.5+fr(i+5)*1.3,spread:(fr(i+9)-.5),r:.6+fr(i+3)*2.2,ph:fr(i+8)*6.28,life:fr(i+11)});
  // ash flakes
  const nAsh=Math.floor(20+P.density*70);
  S.ash=[]; for(let i=0;i<nAsh;i++) S.ash.push({x:fr(i+40)*width,y:fr(i+41)*height,spd:.3+fr(i+42)*.7,r:1+fr(i+43)*2.5,ph:fr(i+44)*6.28});
  // lava river blobs down the flank
  const nLava=10;
  S.lava=[]; for(let i=0;i<nLava;i++){ const t=i/nLava; S.lava.push({t:t,x:width*0.5+Math.sin(i*1.2+fr(i)*3)*width*0.05*(1-t*0.3),w:(24+i*5),ph:fr(i+60)*6.28}); }
  // smoke puffs
  const nSmoke=Math.floor(6+P.smoke*10);
  S.smk=[]; for(let i=0;i<nSmoke;i++) S.smk.push({off:fr(i+80)*6.28,spd:.2+fr(i+81)*.4,drift:(fr(i+82)-.5),r:u*(0.06+fr(i+83)*0.08),ph:fr(i+84)*6.28});
}
image(S.buf,0,0);
const sc=P.scale, T=K.t, hz=S.hz, px=S.peakX, py=S.peakY;
const flare=erupt*(0.7+A.bass*0.8)+K.pulse*0.4;
// crater glow
push(); blendMode(ADD);
const gc = thermal?[0,90]:(ashen?[20,20]:[h+8,92]);
fill(gc[0],gc[1],90,18+flare*22); ellipse(px,py,u*0.4*(0.6+flare*0.7)*sc,u*0.22*(0.6+flare*0.5)*sc);
fill(gc[0],gc[1]-10,95,10+flare*18); ellipse(px,py,u*0.7*(0.6+flare)*sc,u*0.4*(0.6+flare*0.6)*sc);
blendMode(BLEND); pop();
// lava rivers glowing (skip in blueprint -> draw as dashed channel)
for(const l of S.lava){ const yy=py+l.t*(hz-py)+Math.sin(T*0.8+l.ph)*4,
  xx=l.x+Math.sin(T*0.5+l.ph+l.t*4)*width*0.02, pulse=0.6+Math.sin(T*1.4+l.ph)*0.4+flare*0.3;
  if (blueprint){ noFill(); stroke(30,80,70,50+pulse*30); strokeWeight(1.4); ellipse(xx,yy,l.w*sc*0.6,l.w*sc*0.25); noStroke(); }
  else { noStroke(); fill(thermal?10:(h-4), thermal?90:100, (ashen?45:92)*pulse, ashen?70:100); ellipse(xx,yy,l.w*sc*(0.7+flare*0.4),l.w*sc*0.4);
    push(); blendMode(ADD); fill(thermal?30:(h+14),80,100,30*pulse); ellipse(xx,yy,l.w*sc*1.4,l.w*sc*0.7); blendMode(BLEND); pop(); }
}
// smoke plume drifting up (real-time floor)
push(); if(!woodcut && !blueprint) blendMode(BLEND);
for(const s of S.smk){ const life=((T*s.spd*0.12+s.off/6.28)%1),
  yy=py-life*(u*0.6*(0.5+P.smoke)) , xx=px+s.drift*width*0.14*life + Math.sin(T*0.4+s.ph)*u*0.04,
  rr=s.r*(0.5+life*1.6)*sc, a=(1-life)*(ashen?55:38);
  if (thermal){ fill(200-life*80,50,30+life*20,a*0.8); }
  else if (blueprint){ noFill(); stroke(200,40,45,a); strokeWeight(1); }
  else fill(ashen?25:20, ashen?10:18, ashen?55:32, a);
  ellipse(xx,yy,rr,rr*0.9);
}
noStroke(); pop();
// embers rising (real-time floor, never rephases)
push(); if(!blueprint) blendMode(ADD);
for(const e of S.emb){ const life=((T*e.spd*0.18+e.off/6.28+e.life)%1),
  yy=py-life*(u*0.7)*(0.6+erupt*0.7)*sc, xx=px+e.spread*width*0.22*life+Math.sin(T*1.1+e.ph)*u*0.03,
  rr=e.r*sc*(u/600)*(1-life*0.5), a=(1-life)*(60+flare*40);
  if (thermal) fill(60-life*60,90,100,a);
  else if (blueprint){ noFill(); stroke(40,70,80,a*0.7); strokeWeight(1); }
  else if (ashen) fill(25,30,70,a*0.6);
  else fill(h+life*20,90,100,a);
  ellipse(xx,yy,rr,rr);
}
noStroke(); blendMode(BLEND); pop();
// ash falling
for(const a of S.ash){ const yy=(a.y+T*a.spd*26)%(height+20),
  xx=a.x+Math.sin(T*0.4+a.ph)*20*sc, rr=a.r*sc*(u/600)*1.1;
  fill(ashen?30:(thermal?210:20), ashen?8:(thermal?30:15), ashen?60:45, 30);
  ellipse(xx,yy,rr,rr);
}
blendMode(BLEND);
